"box-m\" x=\"205\" y=\"140\" width=\"180\" height=\"90\" rx=\"6\"/><text x=\"295\" y=\"166\" text-anchor=\"middle\" class=\"t-b\">Daily pill</text><text x=\"295\" y=\"185\" text-anchor=\"middle\" class=\"t-s\">dolutegravir-based</text><path class=\"ln-d\" d=\"M385,65 L408,90\"/><path class=\"ln-d\" d=\"M385,185 L408,160\"/></g><g data-step=\"3\"><text x=\"420\" y=\"40\" class=\"t-b\">Confirmed viral rebound by week 96</text><text x=\"420\" y=\"98\" class=\"t-big t-a\">0.9%</text><text x=\"420\" y=\"120\" class=\"t-s\">2 on injections</text><text x=\"560\" y=\"98\" class=\"t-big\">6.4%</text><text x=\"560\" y=\"120\" class=\"t-s\">15 on pills</text><text x=\"420\" y=\"168\" class=\"t-b\">Non-inferior, then superior</text><text x=\"420\" y=\"187\" class=\"t-s\">serious/severe side effects similar</text><text x=\"420\" y=\"215\" class=\"t-s t-m\">open-label; already-suppressed only;</text><text x=\"420\" y=\"233\" class=\"t-s t-m\">cost at scale not studied</text></g></svg>"
